// Wirevo virtual keyboard transport ABI. This is NOT Nordic RADIO/USBD MMIO.
// Firmware submits standard eight-byte keyboard reports from its actual SRAM.
export const KEYBOARD_REPORT_MAP=Object.freeze([0x05,1,0x09,6,0xa1,1,0x05,7,0x19,0xe0,0x29,0xe7,0x15,0,0x25,1,0x75,1,0x95,8,0x81,2,0x95,1,0x75,8,0x81,1,0x95,5,0x75,1,0x05,8,0x19,1,0x29,5,0x91,2,0x95,1,0x75,3,0x91,1,0x95,6,0x75,8,0x15,0,0x25,0x65,0x05,7,0x19,0,0x29,0x65,0x81,0,0xc0]);
const BASE=0x5fffd000;
const ascii=(k,mod,leds)=>{const shift=!!(mod&0x22),caps=!!(leds&2);if(mod&0xdd)return'';if(k>=4&&k<=29)return String.fromCharCode((shift!==caps?65:97)+k-4);if(k>=30&&k<=39)return(shift?'!@#$%^&*()':'1234567890')[k-30];return({40:'\n',42:'\b',43:'\t',44:' ',45:shift?'_':'-',46:shift?'+':'=',47:shift?'{':'[',48:shift?'}':']',49:shift?'|':'\\',51:shift?':':';',52:shift?'"':"'",53:shift?'~':'`',54:shift?'<':',',55:shift?'>':'.',56:shift?'?':'/'})[k]||'';};
const channel=()=>({initialized:false,connected:false,subscribed:false,leds:0,protocol:1,idle:0,text:'',report:Array(8).fill(0),reports:0,events:[],generation:0});
export class NRF52Keyboard{
 constructor(runtime){this.r=runtime;this.usb=channel();this.ble=channel();this.ble.name='Wirevo Keyboard';this.ble.advertising=false;this.ptr=0;this.length=8;this.busy=false;this.result=0;this.epoch=0;}
 owns(a){return a>=BASE&&a<BASE+256;}
 read(a){switch(a-BASE){case 0:return 0x4b420112;case 4:return((this.usb.connected?1:0)|(this.ble.connected&&this.ble.subscribed?2:0)|(this.usb.initialized?4:0)|(this.ble.advertising?8:0)|(this.busy?0x80000000:0))>>>0;case 8:return this.ptr;case 12:return this.result>>>0;case 16:return this.usb.leds;case 20:return this.ble.leds;case 24:return this.length;default:return 0;}}
 write(a,v){switch(a-BASE){case 8:this.ptr=v>>>0;return;case 24:this.length=v>>>0;return;case 32:this.command(v>>>0);return;default:throw Error('Wirevo klavye servis yazmacı geçersiz.');}}
 readBuffer(n,done){const p=this.ptr;if(n<1||n>32||p<0x20000000||p+n>0x20040000){this.result=-3;return;}this.busy=true;const epoch=this.epoch;this.r.dmaRead(p,n,bytes=>{if(epoch!==this.epoch)return;try{done(bytes);}finally{this.busy=false;}});}
 command(op){if(this.busy){this.result=-4;return;}this.result=0;if(op===1){if(!this.usb.initialized)this.usb=channel();this.usb.initialized=true;return;}if(op===2){this.readBuffer(this.length,bytes=>{try{const name=new TextDecoder('utf-8',{fatal:true}).decode(Uint8Array.from(bytes));if(/[\x00-\x1f]/.test(name))throw Error();this.ble.name=name;this.ble.initialized=true;this.ble.advertising=!this.ble.connected;}catch{this.result=-3;}});return;}if(op===5||op===6){const c=op===5?this.usb:this.ble;this.disconnect(c);c.initialized=false;if(op===6)c.advertising=false;return;}if(op!==3&&op!==4){this.result=-5;return;}const c=op===3?this.usb:this.ble;if(!c.initialized){this.result=-1;return;}if(!c.connected||op===4&&!c.subscribed){this.result=-2;return;}if(this.length!==8){this.result=-3;return;}const generation=c.generation;this.readBuffer(8,report=>{if(!c.connected||c.generation!==generation||op===4&&!c.subscribed){this.result=-2;return;}this.accept(c,report);});}
 accept(c,report){if(report[1]||report.slice(2).some(k=>k>(c.backend?.startsWith('TinyUSB')?255:0x65))||new Set(report.slice(2).filter(Boolean)).size!==report.slice(2).filter(Boolean).length){this.result=-3;return;}if(report.slice(2).some(k=>k>=1&&k<=3)){this.result=-3;return;}const previous=new Set(c.report.slice(2)),pressed=report.slice(2).filter(k=>k&&!previous.has(k)),released=c.report.slice(2).filter(k=>k&&!report.slice(2).includes(k));c.report=[...report];c.reports++;for(const key of pressed){if(key===57)c.leds^=2;const ch=ascii(key,report[0],c.leds);if(ch==='\b')c.text=c.text.slice(0,-1);else c.text=(c.text+ch).slice(-4096);}c.events.push({time:this.r.count/64000000,modifier:report[0],pressed,released,report:[...report]});c.events=c.events.slice(-64);}
 disconnect(c){c.connected=false;c.subscribed=false;c.report=Array(8).fill(0);c.generation++;if(c===this.ble)c.advertising=c.initialized;}
 host(d){if(d.transport==='ble'&&this.r.hci?.enabled){if(!this.r.nimbleSession)throw Error('NimBLE alıcısı hazırlanıyor; firmware’i çalıştırın.');return this.r.nimbleSession.host(d);}if(d.transport==='usb'&&this.r.usbDCD?.enabled)return this.r.usbDCD.host(d);const c=d.transport==='usb'?this.usb:d.transport==='ble'?this.ble:null;if(!c)throw Error('USB veya BLE alıcısını seçin.');switch(d.action){case'connect':if(!c.initialized||c===this.ble&&!c.advertising)throw Error('Önce klavye firmware’ini çalıştırın.');c.connected=true;c.report=Array(8).fill(0);c.generation++;if(c===this.ble){c.subscribed=true;c.advertising=false;}else c.enumeration=['GET_DEVICE_DESCRIPTOR','SET_ADDRESS 1','GET_CONFIGURATION_DESCRIPTOR','GET_HID_REPORT_DESCRIPTOR','SET_CONFIGURATION 1'];break;case'disconnect':this.disconnect(c);break;case'subscribe':if(c!==this.ble||!c.connected)throw Error('Önce BLE bağlantısı kurun.');c.subscribed=!!d.enabled;c.report=Array(8).fill(0);c.generation++;break;case'leds':if(!c.connected||!Number.isInteger(d.value)||d.value<0||d.value>31)throw Error('LED raporu 0..31 ve bağlı alıcı gerektirir.');c.leds=d.value;break;case'protocol':if(!c.connected||![0,1].includes(d.value))throw Error('Klavye protokolü 0=boot / 1=report.');c.protocol=d.value;break;case'idle':if(!c.connected||!Number.isInteger(d.value)||d.value<0||d.value>255)throw Error('HID idle değeri 0..255 olmalı.');c.idle=d.value;break;case'clear':c.text='';c.events=[];break;default:throw Error('Klavye alıcısı komutu desteklenmiyor.');}return this.snapshot();}
 snapshot(){const snap=c=>({...c,report:[...c.report],events:c.events.map(e=>({...e,report:[...e.report]}))});const nimble=this.r.nimbleSession?.snapshot();return{nimble,usbDCD:this.r.usbDCD?.snapshot(),model:'Wirevo virtual USB / BLE HID keyboard; no physical USB or RF',usb:{...snap(this.usb),reportMap:[...(this.r.usbDCD?.descriptors.GET_HID_REPORT_DESCRIPTOR||KEYBOARD_REPORT_MAP)],interface:{class:3,subclass:1,protocol:1,endpoint:0x81,packetSize:8}},ble:{...snap(this.ble),service:0x1812,reportMap:[...(nimble?.reportMap||KEYBOARD_REPORT_MAP)],characteristics:{reportMap:0x2a4b,inputReport:0x2a4d,outputReport:0x2a4d,hidInfo:0x2a4a,protocolMode:0x2a4e}}};}
}
